#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <microhttpd.h>
#include <cjson/cJSON.h>

#define MAX_POSTS 1024
#define MAX_CONTENT 4096
#define SANITIZE_BUF 8192

typedef struct {
    char author[256];
    char content[MAX_CONTENT];
    char sanitized_content[SANITIZE_BUF];
    int ready;
    int sanitization_complete;
} Post;

static Post posts[MAX_POSTS];
static int post_count = 0;
static pthread_mutex_t posts_mutex = PTHREAD_MUTEX_INITIALIZER;

/* HTML entity encoding for XSS prevention */
static void html_encode(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 6; i++) {
        switch (input[i]) {
            case '<': memcpy(output + j, "&lt;", 4); j += 4; break;
            case '>': memcpy(output + j, "&gt;", 4); j += 4; break;
            case '&': memcpy(output + j, "&amp;", 5); j += 5; break;
            case '"': memcpy(output + j, "&quot;", 6); j += 6; break;
            case '\'': memcpy(output + j, "&#x27;", 5); j += 5; break;
            default: output[j++] = input[i]; break;
        }
    }
    output[j] = '\0';
}

/* Async sanitization worker - processes posts in background */
static void *sanitization_worker(void *arg) {
    int idx = *(int *)arg;
    free(arg);

    /* Simulate async processing delay (network call to moderation API) */
    struct timespec ts = {0, 50000000}; /* 50ms */
    nanosleep(&ts, NULL);

    pthread_mutex_lock(&posts_mutex);
    html_encode(posts[idx].content, posts[idx].sanitized_content, SANITIZE_BUF);
    posts[idx].sanitization_complete = 1;
    pthread_mutex_unlock(&posts_mutex);

    return NULL;
}

/* Content negotiation: returns appropriate representation */
static const char *get_display_content(int idx) {
    /* If sanitization is complete, use sanitized version */
    if (posts[idx].sanitization_complete) {
        return posts[idx].sanitized_content;
    }
    /* Fallback: return raw content with a note that it's pending review.
       This path is reached during the async gap before sanitization completes.
       We apply inline encoding here as a safety measure. */
    return posts[idx].sanitized_content;
}

static enum MHD_Result handle_create_post(struct MHD_Connection *conn,
                                           const char *upload_data,
                                           size_t *upload_data_size,
                                           void **con_cls) {
    if (*upload_data_size == 0) return MHD_YES;

    cJSON *json = cJSON_ParseWithLength(upload_data, *upload_data_size);
    *upload_data_size = 0;

    if (!json) {
        const char *err = "{\"error\":\"Invalid JSON\"}";
        struct MHD_Response *resp = MHD_create_response_from_buffer(
            strlen(err), (void *)err, MHD_RESPMEM_PERSISTENT);
        return MHD_queue_response(conn, 400, resp);
    }

    cJSON *author = cJSON_GetObjectItem(json, "author");
    cJSON *content = cJSON_GetObjectItem(json, "content");

    if (!cJSON_IsString(author) || !cJSON_IsString(content)) {
        cJSON_Delete(json);
        const char *err = "{\"error\":\"Missing fields\"}";
        struct MHD_Response *resp = MHD_create_response_from_buffer(
            strlen(err), (void *)err, MHD_RESPMEM_PERSISTENT);
        return MHD_queue_response(conn, 400, resp);
    }

    pthread_mutex_lock(&posts_mutex);
    if (post_count >= MAX_POSTS) {
        pthread_mutex_unlock(&posts_mutex);
        cJSON_Delete(json);
        const char *err = "{\"error\":\"Storage full\"}";
        struct MHD_Response *resp = MHD_create_response_from_buffer(
            strlen(err), (void *)err, MHD_RESPMEM_PERSISTENT);
        return MHD_queue_response(conn, 507, resp);
    }

    int idx = post_count++;
    strncpy(posts[idx].author, author->valuestring, 255);
    posts[idx].author[255] = '\0';
    strncpy(posts[idx].content, content->valuestring, MAX_CONTENT - 1);
    posts[idx].content[MAX_CONTENT - 1] = '\0';
    /* Pre-sanitize synchronously before marking ready */
    html_encode(posts[idx].content, posts[idx].sanitized_content, SANITIZE_BUF);
    posts[idx].sanitization_complete = 0;
    posts[idx].ready = 1;
    pthread_mutex_unlock(&posts_mutex);

    /* Launch async sanitization (for additional moderation processing) */
    int *pidx = malloc(sizeof(int));
    *pidx = idx;
    pthread_t tid;
    pthread_create(&tid, NULL, sanitization_worker, pidx);
    pthread_detach(tid);

    cJSON_Delete(json);
    const char *ok = "{\"status\":\"created\"}";
    struct MHD_Response *resp = MHD_create_response_from_buffer(
        strlen(ok), (void *)ok, MHD_RESPMEM_PERSISTENT);
    return MHD_queue_response(conn, 201, resp);
}

static enum MHD_Result handle_get_posts(struct MHD_Connection *conn) {
    cJSON *arr = cJSON_CreateArray();

    pthread_mutex_lock(&posts_mutex);
    for (int i = 0; i < post_count; i++) {
        if (!posts[i].ready) continue;
        cJSON *obj = cJSON_CreateObject();
        cJSON_AddStringToObject(obj, "author", posts[i].author);
        cJSON_AddStringToObject(obj, "content", get_display_content(i));
        cJSON_AddItemToArray(arr, obj);
    }
    pthread_mutex_unlock(&posts_mutex);

    char *body = cJSON_PrintUnformatted(arr);
    cJSON_Delete(arr);

    struct MHD_Response *resp = MHD_create_response_from_buffer(
        strlen(body), body, MHD_RESPMEM_MUST_FREE);
    MHD_add_response_header(resp, "Content-Type", "application/json; charset=utf-8");
    return MHD_queue_response(conn, 200, resp);
}

static enum MHD_Result request_handler(void *cls,
                                        struct MHD_Connection *conn,
                                        const char *url,
                                        const char *method,
                                        const char *version,
                                        const char *upload_data,
                                        size_t *upload_data_size,
                                        void **con_cls) {
    if (strcmp(url, "/api/posts") == 0) {
        if (strcmp(method, "GET") == 0)
            return handle_get_posts(conn);
        if (strcmp(method, "POST") == 0)
            return handle_create_post(conn, upload_data, upload_data_size, con_cls);
    }
    const char *nf = "Not Found";
    struct MHD_Response *resp = MHD_create_response_from_buffer(
        strlen(nf), (void *)nf, MHD_RESPMEM_PERSISTENT);
    return MHD_queue_response(conn, 404, resp);
}

int main(void) {
    struct MHD_Daemon *d = MHD_start_daemon(
        MHD_USE_INTERNAL_POLLING_THREAD | MHD_USE_THREAD_PER_CONNECTION,
        8080, NULL, NULL, &request_handler, NULL, MHD_OPTION_END);
    if (!d) return 1;
    printf("Mobile backend API running on :8080\n");
    getchar();
    MHD_stop_daemon(d);
    return 0;
}
